package com.order.order_service.controller;
import com.order.order_service.entity.OrderStatus;import com.order.order_service.service.OrderService;import com.order.order_service.service.OrderQueryService;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/orders") public class InternalOrderController {private final OrderService service;private final OrderQueryService queries;private final String deliveryKey;private final String catalogKey;public InternalOrderController(OrderService s,OrderQueryService q,@Value("${delivery-service.internal-key}") String k,@Value("${catalog-service.internal-key:local-internal-key-change-me}")String catalogKey){service=s;queries=q;deliveryKey=k;this.catalogKey=catalogKey;}
 @GetMapping("/review-eligibility")public Map<String,Boolean> reviewEligibility(@RequestHeader("X-Internal-Key")String provided,@RequestParam long userId,@RequestParam long restaurantId){check(provided,catalogKey);return Map.of("eligible",service.hasDeliveredOrder(userId,restaurantId));}
 @GetMapping("/{id}/owner-access")public Map<String,Boolean> ownerAccess(@RequestHeader("X-Internal-Key")String provided,@PathVariable long id,@RequestParam long ownerId){check(provided,deliveryKey);return Map.of("allowed",queries.ownedByRestaurantOwner(id,ownerId));}
 @PutMapping("/{id}/status") @ResponseStatus(HttpStatus.NO_CONTENT) public void update(@RequestHeader("X-Internal-Key") String provided,@PathVariable long id,@RequestBody Map<String,String> body){check(provided,deliveryKey);try{service.applyDeliveryStatus(id,OrderStatus.valueOf(body.get("status")));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid order status",e);}}
 private void check(String provided,String expected){if(!MessageDigest.isEqual(provided.getBytes(StandardCharsets.UTF_8),expected.getBytes(StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid service credential");}
}
